import datetime
from dataclasses import dataclass

GRACE_PERIOD_DAYS = 14
MAX_RENEWAL_DAYS = 365
BASE_RATE_PER_DAY = 0.50


class PermitError(Exception):
    pass


@dataclass
class Account:
    holder: str
    balance: float


def get_current_permit(records, plate):
    return records[plate]


def charge_renewal_fee(account, amount):
    if account.balance < amount:
        raise PermitError("insufficient balance to cover renewal fee")
    account.balance -= amount
    return True


def renew_permit(records, account, plate, requested_days):
    if requested_days <= 0 or requested_days > MAX_RENEWAL_DAYS:
        raise ValueError("requested_days out of range")

    today = datetime.date.today()
    try:
        permit = get_current_permit(records, plate)
        expires_on = datetime.date.fromisoformat(permit["expires_on"])
    except KeyError:
        expires_on = today

    lapsed_days = (today - expires_on).days
    fee_multiplier = 1.5 if lapsed_days > GRACE_PERIOD_DAYS else 1.0
    fee = round(requested_days * BASE_RATE_PER_DAY * fee_multiplier, 2)

    try:
        charge_renewal_fee(account, fee)
        new_expiry = max(today, expires_on) + datetime.timedelta(days=requested_days)
        records[plate] = {
            "plate": plate,
            "expires_on": new_expiry.isoformat(),
            "renewed_on": today.isoformat(),
        }
        return records[plate]
    except Exception:
        return None


def describe_renewal(records, account, plate, requested_days):
    result = renew_permit(records, account, plate, requested_days)
    if result is None:
        return f"Could not renew permit for {plate}. Please try again or contact support."
    return f"Permit for {plate} renewed through {result['expires_on']}."
